from dataclasses import dataclass
from typing import Any

import torch

from src.mythosmini.config import ARC_DATASET, ARC_FEWSHOT_COUNT, ARC_QUESTION_COUNT
from src.mythosmini.benchmarks.scorer import ScoredPair, continuation_log_likelihoods
from src.mythosmini.model.transformer import MythosMini


@dataclass(frozen=True)
class ArcQuestion:
    question: str
    choices: list[str]
    answer_index: int


def answer_index_of(record: dict[str, Any]) -> int | None:
    labels = [str(label) for label in record["choices"]["label"]]
    answer_key = str(record["answerKey"])
    if answer_key not in labels:
        return None
    return labels.index(answer_key)


def record_to_question(record: dict[str, Any]) -> ArcQuestion | None:
    index = answer_index_of(record)
    if index is None:
        return None
    return ArcQuestion(
        question=str(record["question"]),
        choices=[str(choice) for choice in record["choices"]["text"]],
        answer_index=index,
    )


def format_example(question: str, answer: str) -> str:
    return f"Question: {question}\nAnswer: {answer}"


def build_fewshot_prefix(examples: list[ArcQuestion]) -> str:
    solved = [
        format_example(example.question, example.choices[example.answer_index])
        for example in examples
    ]
    return "\n\n".join(solved) + "\n\n" if solved else ""


def load_arc_questions(
    question_count: int = ARC_QUESTION_COUNT, fewshot_count: int = ARC_FEWSHOT_COUNT
) -> tuple[str, list[ArcQuestion]]:
    from datasets import load_dataset

    train = load_dataset(ARC_DATASET, name="ARC-Easy", split="train")
    test = load_dataset(ARC_DATASET, name="ARC-Easy", split="test")
    fewshot: list[ArcQuestion] = []
    for record in train:
        question = record_to_question(dict(record))
        if question is not None:
            fewshot.append(question)
        if len(fewshot) >= fewshot_count:
            break
    questions: list[ArcQuestion] = []
    for record in test:
        question = record_to_question(dict(record))
        if question is not None:
            questions.append(question)
        if len(questions) >= question_count:
            break
    if not questions:
        raise ValueError(f"no arc questions loaded from {ARC_DATASET}")
    return build_fewshot_prefix(fewshot), questions


def arc_accuracy(
    model: MythosMini,
    prefix: str,
    questions: list[ArcQuestion],
    batch_size: int,
    device: str,
    dtype: torch.dtype,
) -> float:
    pairs: list[ScoredPair] = []
    spans: list[int] = []
    for question in questions:
        context_text = prefix + f"Question: {question.question}\nAnswer:"
        context = list(context_text.encode("utf-8"))
        spans.append(len(question.choices))
        for choice in question.choices:
            pairs.append(ScoredPair(context=context, continuation=list(f" {choice}".encode())))
    likelihoods = continuation_log_likelihoods(model, pairs, batch_size, device, dtype)
    correct = 0
    cursor = 0
    for question, span in zip(questions, spans, strict=True):
        scores = likelihoods[cursor : cursor + span]
        cursor += span
        if scores.index(max(scores)) == question.answer_index:
            correct += 1
    return 100.0 * correct / len(questions)
